"use client";import {useState} from "react";import {supabase} from "../../lib/supabase";export default function Login(){const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[msg,setMsg]=useState("");const login=async()=>{const{error}=await supabase.auth.signInWithPassword({email,password});setMsg(error?.message||"Login successful");if(!error)location.href="/dashboard"};const signup=async()=>{const{error}=await supabase.auth.signUp({email,password});setMsg(error?.message||"Signup submitted. Administrator approval is required.")};return <div className="card" style={{maxWidth:430,margin:"70px auto"}}><h2>Secure Access</h2><p className="muted">GPCC Finance Portal</p><input className="input" type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} style={{marginBottom:10}}/><input className="input" type="password" placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)} style={{marginBottom:15}}/><div className="actions"><button className="btn" onClick={login}>Login</button><button className="btn secondary" onClick={signup}>Sign Up</button></div><p>{msg}</p></div>}